// Edit this list to change what the newsletter reads.
const feeds = [
  {
    "source": "TechCrunch AI",
    "url": "https://techcrunch.com/category/artificial-intelligence/feed/"
  },
  {
    "source": "VentureBeat AI",
    "url": "https://venturebeat.com/category/ai/feed/"
  },
  {
    "source": "The Verge \u2013 AI",
    "url": "https://www.theverge.com/rss/ai-artificial-intelligence/index.xml"
  },
  {
    "source": "MIT Technology Review",
    "url": "https://www.technologyreview.com/feed/"
  },
  {
    "source": "Wired \u2013 AI",
    "url": "https://www.wired.com/feed/tag/ai/latest/rss"
  },
  {
    "source": "Ars Technica",
    "url": "https://feeds.arstechnica.com/arstechnica/technology-lab"
  },
  {
    "source": "ZDNet \u2013 AI",
    "url": "https://www.zdnet.com/topic/artificial-intelligence/rss.xml"
  },
  {
    "source": "Analytics India Magazine",
    "url": "https://analyticsindiamag.com/feed/"
  },
  {
    "source": "Google Research Blog",
    "url": "https://blog.google/technology/ai/rss/"
  },
  {
    "source": "Microsoft AI Blog",
    "url": "https://blogs.microsoft.com/ai/feed/"
  },
  {
    "source": "AWS ML Blog",
    "url": "https://aws.amazon.com/blogs/machine-learning/feed/"
  },
  {
    "source": "Hugging Face Blog",
    "url": "https://huggingface.co/blog/feed.xml"
  },
  {
    "source": "KDnuggets",
    "url": "https://www.kdnuggets.com/feed"
  },
  {
    "source": "Google News \u2013 AI (7d)",
    "url": "https://news.google.com/rss/search?q=artificial+intelligence+when:7d&hl=en-US&gl=US&ceid=US:en"
  },
  {
    "source": "Google News \u2013 AI agents (7d)",
    "url": "https://news.google.com/rss/search?q=%22AI+agents%22+OR+%22agentic+AI%22+when:7d&hl=en-US&gl=US&ceid=US:en"
  },
  {
    "source": "Google News \u2013 telecom AI",
    "url": "https://news.google.com/rss/search?q=telecom+AI+OR+%22network+automation%22+when:7d&hl=en-US&gl=US&ceid=US:en"
  },
  {
    "source": "Google News \u2013 data platforms",
    "url": "https://news.google.com/rss/search?q=%22data+platform%22+OR+%22data+governance%22+when:7d&hl=en-US&gl=US&ceid=US:en"
  },
  {
    "source": "arXiv cs.AI (new)",
    "url": "https://rss.arxiv.org/rss/cs.AI"
  }
];
return feeds.map(f => ({ json: f }));

// Flatten every RSS item, keep last 7 days, de-duplicate, cap the list.
const DAYS = 7;
const MAX  = 70;
const cutoff = Date.now() - DAYS * 24 * 60 * 60 * 1000;

// RSS is messy: title/creator/author can arrive as a string, an object
// ({ _: 'x' }, { name: 'x' }, { '#': 'x' }) or an array. Flatten anything to text.
const asText = (v) => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return v.map(asText).filter(Boolean).join(' ');
  if (typeof v === 'object') {
    return asText(v.name ?? v._ ?? v['#'] ?? v.value ?? v.title ?? v.href ?? '');
  }
  return String(v);
};

const strip = (h) => asText(h)
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&#\d+;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const norm = (t) => strip(t).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 70);

const seen = new Set();
const out  = [];

for (const item of $input.all()) {
  const j = item.json || {};

  let title = strip(j.title);
  if (!title) continue;

  const when = new Date(
    asText(j.isoDate) || asText(j.pubDate) || asText(j.date) || Date.now()
  ).getTime();
  if (isFinite(when) && when < cutoff) continue;

  const key = norm(title);
  if (seen.has(key)) continue;
  seen.add(key);

  const link = strip(j.link) || strip(j.guid);
  const host = (link.split('/')[2] || '').replace(/^www\./, '');

  // --- find a usable picture for this article -------------------------
  const html = [asText(j['content:encoded']), asText(j.content), asText(j.summary)].join(' ');
  const junk = /feedburner|gravatar|pixel|1x1|spacer|blank\.|doubleclick|badge|icon/i;
  let image = '';
  const enc = j.enclosure && (j.enclosure.url || j.enclosure.href);
  const media = j['media:content'] && (j['media:content'].url || (j['media:content'].$ || {}).url);
  const inline = (html.match(/<img[^>]+src=["']([^"']+)["']/i) || [])[1];
  for (const cand of [enc, media, inline]) {
    if (cand && /^https?:\/\//i.test(cand) && !junk.test(cand)) { image = cand; break; }
  }

  // Google News puts the publisher on the end of the headline: "Headline - Politico"
  let source = strip(j.creator) || strip(j.author);
  const tail = title.match(/\s-\s([^-]{2,40})$/);
  if (!source && tail) { source = tail[1].trim(); title = title.slice(0, tail.index).trim(); }
  if (!source) source = host;

  out.push({
    title,
    link,
    image,
    date:    new Date(isFinite(when) ? when : Date.now()).toISOString().slice(0, 10),
    source,
    summary: strip(j.contentSnippet || j.content || j.summary).slice(0, 700),
  });
}

// Articles WITH a picture come first — the newsletter is picture-led, and a
// story we can illustrate is worth more than one we cannot.
out.sort((a, b) => {
  if (!!b.image !== !!a.image) return b.image ? 1 : -1;
  return b.date > a.date ? 1 : -1;
});

// No single publisher may dominate. Without this, arXiv alone (hundreds of
// items a day, never illustrated) fills the entire budget.
const PER_SOURCE = 6;
const tally = {};
const balanced = out.filter((x) => {
  const k = (x.source || 'unknown').toLowerCase();
  tally[k] = (tally[k] || 0) + 1;
  return tally[k] <= PER_SOURCE;
});
out.length = 0;
out.push(...balanced);

if (!out.length) {
  throw new Error('No articles survived filtering — check the feeds, or raise DAYS.');
}

return [{ json: { count: out.length, articles: out.slice(0, MAX) } }];

