// Pull the JSON object out of Gemini's response, tolerating stray fences.
const raw = $json?.candidates?.[0]?.content?.parts?.[0]?.text;
if (!raw) throw new Error('Gemini returned no text. Full response: ' + JSON.stringify($json).slice(0, 800));

let txt = raw.trim()
  .replace(/^```(?:json)?/i, '')
  .replace(/```$/, '')
  .trim();

const first = txt.indexOf('{');
const last  = txt.lastIndexOf('}');
if (first > 0 || last < txt.length - 1) txt = txt.slice(first, last + 1);

let issue;
try {
  issue = JSON.parse(txt);
} catch (e) {
  throw new Error('Could not parse Gemini JSON: ' + e.message + '\n---\n' + txt.slice(0, 1200));
}

if (!issue.sections || !issue.sections.length) throw new Error('Gemini returned no sections.');
return [{ json: issue }];

// Give every story tile the picture that came with its own article.
//
// No image generation, no image search, no API keys. Each article's RSS entry
// already carried a hero image (scraped in "Normalise & Dedupe"); Gemini tells
// us which article a tile came from via "ref", and we join the two here.
const issue    = $input.first().json;
const articles = $('Normalise & Dedupe').first().json.articles || [];

let photos = 0, tiles = 0;

for (const s of issue.sections || []) {
  for (const t of (s.items || [])) {
    if (t.type !== 'story' && t.type !== 'visual') continue;
    tiles++;
    const art = articles[Number(t.ref) - 1];
    if (!art) continue;

    if (art.image) {
      t.image_url    = art.image;
      t.image_source = art.source;   // credit line under the picture
      t.image_page   = art.link;
      photos++;
    }
    if (!t.source) t.source = art.source;
    if (!t.date)   t.date   = art.date;
  }
  // Cover hero: reuse the picture from the week's lead story.
  if (s.type === 'cover' && !s.hero_url) {
    const lead = articles.find((x) => x.image);
    if (lead) {
      s.hero_url     = lead.image;
      s.image_source = lead.source;
    }
  }
}

return [{
  json: { issue, images: {}, tilesNeedingArt: tiles, photosAttached: photos },
}];

/* =====================================================================
   InfiniAI Pulse — HTML builder  (poster edition)
   ---------------------------------------------------------------------
   Turns the "issue" JSON produced by Gemini into three HTML documents:
     index.html   the newsletter body
     header.html  running header (repeats on EVERY page)
     footer.html  running footer  (repeats on EVERY page)

   Layout model
   ------------
   The body is a stack of ROWS. Each row holds 1-3 TILES whose widths are
   given as a weight (w: 1 | 2 | 3 out of 3). A row never splits across a
   page, so pagination stays predictable no matter how much news there is.
   That is what gives the poster/collage feel while still printing cleanly.

   Visuals come from three places, all optional per tile:
     - image_url   a real picture from the article's RSS feed
     - ai_image    a generated illustration (data URI), keyed by ai_key
     - drawn       infographic tiles built here in HTML/CSS: matrix,
                   ranked, compare, chart, stat, quote

   This exact file is what you paste into the n8n "Build HTML" Code node
   (everything above the "n8n glue" comment).
   ===================================================================== */

const BRAND = {
  navy:  '#205781',
  teal:  '#4F959D',
  cyan:  '#29C5D6',
  mint:  '#98D2C0',
  ink:   '#16323F',
  grey:  '#6B7F88',
  line:  '#DCE7EB',
  tint:  '#F3F8FA',
};

const PALETTE = ['#205781', '#4F959D', '#29C5D6', '#F0A500', '#8E44AD',
                 '#1B7FC4', '#4CAF50', '#E4572E', '#0B3C8D', '#00A6A6'];

/* ------------------------------------------------------------------ */
/* helpers                                                             */
/* ------------------------------------------------------------------ */
const esc = (s = '') => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const pick = (i) => PALETTE[(i % PALETTE.length + PALETTE.length) % PALETTE.length];

/** QuickChart: free, no API key, returns a PNG straight from a URL. */
function chartUrl(config, w = 700, h = 420, bg = 'white') {
  return `https://quickchart.io/chart?w=${w}&h=${h}&bkg=${bg}&v=4&c=` +
         encodeURIComponent(JSON.stringify(config));
}

function specToChart(spec = {}) {
  const type = (spec.type || 'bar').toLowerCase();
  const labels = spec.labels || [];
  const values = spec.values || [];
  const colours = labels.map((_, i) => pick(i + (spec.colorOffset || 0)));
  const isRound = type === 'pie' || type === 'doughnut';

  const common = {
    plugins: {
      legend: {
        display: isRound, position: 'right',
        labels: { font: { size: 12 }, boxWidth: 13, padding: 10 },
      },
      datalabels: {
        display: true,
        color: isRound ? '#fff' : '#16323F',
        anchor: type === 'bar' ? 'end' : 'center',
        align:  type === 'bar' ? 'end' : 'center',
        font: { size: 12, weight: 'bold' },
      },
    },
  };

  if (isRound) {
    return { type,
      data: { labels, datasets: [{ data: values, backgroundColor: colours, borderColor: '#fff', borderWidth: 2 }] },
      options: { ...common, cutout: type === 'doughnut' ? '55%' : undefined } };
  }
  if (type === 'line') {
    return { type: 'line',
      data: { labels, datasets: [{ label: spec.seriesLabel || '', data: values,
        borderColor: BRAND.navy, backgroundColor: 'rgba(32,87,129,0.15)',
        fill: true, tension: 0.35, pointBackgroundColor: BRAND.cyan, pointRadius: 4 }] },
      options: { ...common, scales: { y: { beginAtZero: true, grid: { color: '#E8EEF1' } }, x: { grid: { display: false } } } } };
  }
  return { type: 'bar',
    data: { labels, datasets: [{ label: spec.seriesLabel || '', data: values, backgroundColor: colours, borderRadius: 5 }] },
    options: { ...common,
      indexAxis: type === 'horizontalbar' ? 'y' : 'x',
      scales: { y: { beginAtZero: true, grid: { color: '#E8EEF1' } }, x: { grid: { display: false } } } } };
}

/**
 * Ask for the picture at the size it will actually print, via wsrv.nl — a free
 * image proxy, no key required.
 *
 * Chromium embeds every image at its source resolution regardless of display
 * size, so a 3000px press photo shown at 60mm still carries 3000px into the
 * PDF. A 60mm tile needs 709px at 300dpi; anything beyond that is invisible
 * weight. This is what takes an issue from ~10MB to ~2-3MB.
 *
 * If the proxy is unreachable the <img> onerror handler falls back to a
 * gradient, so a bad day for wsrv.nl costs a picture, never the issue.
 */
function sized(url, w) {
  if (!url || !/^https?:\/\//i.test(url)) return url;   // data: URIs pass through
  return `https://wsrv.nl/?url=${encodeURIComponent(url)}&w=${w}&q=82&output=jpg&we`;
}

/** Printed width in px at 300dpi for a tile of weight w (1-3 of a 186mm row). */
function pxFor(w) {
  return ({ 1: 900, 2: 1500, 3: 1800 })[Math.max(1, Math.min(3, Number(w) || 1))];
}

/** Resolve a tile's picture: real article image first, then AI image. */
function picture(t, images = {}) {
  if (t.image_url) return t.image_url;
  if (t.ai_key && images[t.ai_key]) return images[t.ai_key];
  return null;
}

/**
 * A remote image can still fail at print time — the host is slow, rate-limits,
 * or 404s — and Chromium then draws a broken-image icon, which looks worse than
 * having no picture at all. Gotenberg runs JavaScript, so we hide the <img> and
 * let the tile's own background show through instead.
 */
/**
 * Credit line for a borrowed picture. These infographics are other people's
 * work — naming the source is both good practice and useful to the reader,
 * who can go and find the original.
 */
function credit(t) {
  if (!t.image_source) return '';
  return `<span class="credit">Source: ${esc(t.image_source)}</span>`;
}

function onImgError(gradient) {
  const bg = gradient ? `this.parentNode.style.background='${gradient}';` : '';
  return ` onerror="this.style.display='none';${bg}this.parentNode.classList.add('img-failed')"`;
}

/* ------------------------------------------------------------------ */
/* CSS                                                                 */
/* ------------------------------------------------------------------ */
function css() {
  return `
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&family=Inter:wght@400;500;600;700&display=swap');

/* NO @page RULE ON PURPOSE. A CSS @page margin overrides the margins passed
   to Chromium's printToPDF, which collapses the space reserved for the running
   header and footer. Paper size and margins are set by the Gotenberg node. */

* { box-sizing: border-box; }
body { margin: 0; padding: 0;
  font-family: 'Inter','Segoe UI',Arial,sans-serif;
  font-size: 9.2pt; line-height: 1.36; color: ${BRAND.ink};
  -webkit-print-color-adjust: exact; print-color-adjust: exact; }
h1,h2,h3,h4 { font-family: 'Poppins','Segoe UI',Arial,sans-serif; margin: 0; }
img { max-width: 100%; }

/* ---- rows & tiles ------------------------------------------------ */
/* align-items:flex-start, NOT stretch. Stretching every tile to the height of
   its tallest neighbour is what makes a page read as a dashboard grid. Letting
   tiles keep their natural height gives the ragged, collage feel of the
   hand-made issues. */
.row { display: flex; gap: 6px; margin-bottom: 6px;
       align-items: flex-start; break-inside: avoid; page-break-inside: avoid; }
/* No overflow:hidden on .tile — it silently clips text when a row's height
   is decided by a taller neighbour. Round the inner images instead. */
.tile { border-radius: 11px; position: relative;
        display: flex; flex-direction: column; min-width: 0; }
.t-story .pic, .t-story .nopic, .t-image img, .t-chart .head { border-radius: 10px 10px 0 0; }
.w1 { flex: 1 1 0; } .w2 { flex: 2 1 0; } .w3 { flex: 3 1 0; }

/* ---- masthead band ----------------------------------------------- */
.band { background: ${BRAND.navy}; color: #fff; border-radius: 9px;
        padding: 11px 16px; font-size: 10.4pt; font-weight: 500; margin-bottom: 8px; }

/* Per-section summary band — the navy box that introduces each page. */
/* The navy band sits under the masthead but INDENT from the left, clearing the
   circular logo — the same offset as the hand-made issues, where the band tucks
   in beneath the wordmark rather than spanning the whole page. */
.sec-summary { background: ${BRAND.navy}; color: #fff; border-radius: 7px;
  padding: 7px 13px; font-size: 8.8pt; line-height: 1.34;
  margin: 0 0 7px 38mm; font-weight: 500;
  break-after: avoid; page-break-after: avoid; }
.band .meta { display: block; font-size: 8pt; letter-spacing: .15em;
        text-transform: uppercase; color: ${BRAND.mint}; font-weight: 700; margin-bottom: 4px; }

.meta-line { font-size: 8pt; letter-spacing: .15em; text-transform: uppercase;
  color: ${BRAND.teal}; font-weight: 700; margin-bottom: 7px; }
.chips { display: flex; flex-wrap: wrap; gap: 5px; margin-bottom: 6px; }
.chip { border-radius: 7px; padding: 7px 14px; color: #fff;
        font-family: 'Poppins',sans-serif; font-weight: 600; font-size: 9.2pt; }

/* ---- section heading --------------------------------------------- */
.sec-title { display: block; border-left: 5px solid ${BRAND.cyan}; padding-left: 9px;
  font-size: 12.5pt; font-weight: 700; color: ${BRAND.navy};
  margin: 7px 0 6px; line-height: 1.15;
  break-after: avoid; page-break-after: avoid; }
.sec-sub { color: ${BRAND.grey}; font-size: 9pt; margin: -4px 0 9px 16px; }

/* ---- tile: picture (the workhorse of the poster) -------------------
   No card, no border, no tint. The picture sits on the page at its own
   aspect ratio, exactly as in the hand-made issues. */
/* HEIGHT MUST BE CAPPED. With height:auto a portrait infographic at w:2 renders
   ~160mm tall. Rows are break-inside:avoid, so a giant row that will not fit in
   the space left jumps to the next page whole and leaves the gap behind it.
   That single rule was the cause of both the white space and the page bloat. */
.t-visual { display: block; }
.t-visual img { width: 100%; height: 58mm; object-fit: cover; object-position: top;
  display: block; border-radius: 10px; }
.t-visual.tall img { height: 84mm; }
.t-visual .cap { padding: 5px 2px 0; font-size: 8pt; color: ${BRAND.grey}; line-height: 1.3; }
.credit { display: block; margin-top: 2px; font-size: 6.8pt; color: #9AAAB2;
   letter-spacing: .02em; }

/* ---- tile: story -------------------------------------------------- */
.t-story { background: #fff; border: 1px solid ${BRAND.line}; }
/* height:auto — let the picture keep its shape rather than be cropped to a
   uniform strip. A press photo and a tall diagram should not look alike. */
.t-story .pic { width: 100%; height: 32mm; object-fit: cover; display: block; }
.t-story .line { font-size: 8.8pt; margin: 0 0 5px; color: ${BRAND.ink}; }
.t-story .nopic { height: 13mm; flex: none; display: flex; align-items: center; padding: 0 12px;
   font-family:'Poppins',sans-serif; font-weight: 800; font-size: 13pt;
   letter-spacing: .04em; color: rgba(255,255,255,.9); }
.t-story .body { padding: 7px 9px 8px; flex: 1; }
.t-story .tag { display: inline-block; font-size: 6.8pt; font-weight: 700; letter-spacing: .1em;
   text-transform: uppercase; color: #fff; padding: 2px 7px; border-radius: 20px; margin-bottom: 5px; }
.t-story h3 { font-size: 10.6pt; line-height: 1.24; color: ${BRAND.navy}; margin-bottom: 4px; }
.t-story .src { font-size: 7.4pt; color: ${BRAND.grey}; margin-bottom: 5px; }
.t-story ul { margin: 0 0 6px 13px; padding: 0; font-size: 8.6pt; }
.t-story li { margin-bottom: 2px; }
.t-story .why { background: #fff; border-left: 3px solid ${BRAND.cyan};
   border-radius: 6px; padding: 6px 8px; font-size: 8.2pt; }
.t-story .why b { display: block; font-family:'Poppins',sans-serif; font-size: 7.2pt;
   letter-spacing: .07em; text-transform: uppercase; color: ${BRAND.navy}; margin-bottom: 1px; }

/* ---- tile: stat ---------------------------------------------------- */
.t-stat { color: #fff; padding: 10px 11px; justify-content: center; min-height: 20mm; }
.t-stat .n { font-family:'Poppins',sans-serif; font-size: 22pt; font-weight: 800; line-height: 1; }
.t-stat .l { font-size: 8.2pt; opacity: .93; margin-top: 5px; line-height: 1.3; }

/* ---- tile: image / hero --------------------------------------------
   NOTE: these tiles are display:block, not flex. A percentage width on an
   <img> inside a flex column resolves against an indefinite containing
   block and overflows. Block layout gives it a definite width. Same
   reason applies to .t-chart below. */
.t-image { background: ${BRAND.tint}; border: 1px solid ${BRAND.line}; display: block; }
.t-image img { width: 100%; height: 36mm; display: block; object-fit: cover; }
.t-image .cap { padding: 6px 10px 8px; font-size: 8pt; color: ${BRAND.grey}; background: #fff; }
.t-hero img { height: 38mm; }
.t-noimg { min-height: 32mm; justify-content: flex-end; padding: 12px 14px; }
.t-noimg .cap { color: #fff; font-family:'Poppins',sans-serif;
   font-size: 10.5pt; font-weight: 600; line-height: 1.3; }

/* ---- tile: quote ---------------------------------------------------- */
.t-quote { background: linear-gradient(120deg, ${BRAND.navy}, ${BRAND.teal});
   color: #fff; padding: 14px 16px; justify-content: center; min-height: 30mm; }
.t-quote .q { font-family:'Poppins',sans-serif; font-size: 11.5pt; font-weight: 600; line-height: 1.35; }
.t-quote .who { margin-top: 7px; font-size: 8.4pt; color: ${BRAND.mint}; }

/* ---- tile: chart ---------------------------------------------------- */
.t-chart { background: #fff; border: 1px solid ${BRAND.line}; display: block; }
.t-chart .head { background: ${BRAND.navy}; color: #fff; padding: 7px 12px; }
.t-chart .head .k { font-size: 7.4pt; letter-spacing: .12em; text-transform: uppercase;
   color: ${BRAND.mint}; font-weight: 700; }
.t-chart .head h3 { font-size: 10.6pt; }
.t-chart .plot { padding: 8px 10px 2px; }
.t-chart .plot img { width: 100%; max-height: 52mm; object-fit: contain; display: block; }
.t-chart .cap { padding: 0 12px 9px; font-size: 7.8pt; color: ${BRAND.grey}; }

/* ---- tile: matrix (2x2 quadrant) ------------------------------------ */
.t-matrix { background: #fff; border: 1px solid ${BRAND.line}; padding: 11px 12px 12px; }
.t-matrix h3 { font-size: 11pt; color: ${BRAND.navy}; margin-bottom: 8px; }
.mx { display: flex; }
.mx .ylab { width: 17mm; flex: none; display: flex; flex-direction: column; }
.mx .ylab div { flex: 1; display: flex; align-items: center; justify-content: flex-end;
   text-align: right; padding-right: 6px; font-size: 7.4pt; color: ${BRAND.grey};
   font-weight: 600; line-height: 1.2; }
.mx .grid { flex: 1; }
.mx .xlab { display: flex; margin-bottom: 4px; }
