/* ------------------------------------------------------------------ */
/* tile renderers                                                      */
/* ------------------------------------------------------------------ */
const TILE = {
  /** Image-first news tile: picture dominates, one line of text earns its place. */
  story(t, i, images) {
    const c = t.color || pick(i);
    const img = picture(t, images);
    return `
<div class="tile t-story w${t.w || 1}" style="border-top:4px solid ${c}">
  ${img
    ? `<img class="pic" src="${esc(sized(img, pxFor(t.w)))}"${onImgError(`linear-gradient(120deg,${c},${BRAND.navy})`)}>`
    : `<div class="nopic" style="background:linear-gradient(120deg,${c},${BRAND.navy})">${esc(t.tag || '')}</div>`}
  <div class="body">
    <span class="tag" style="background:${c}">${esc(t.tag || 'AI')}</span>
    <h3>${esc(t.title)}</h3>
    ${t.why_it_matters ? `<p class="line">${esc(t.why_it_matters)}</p>` : ''}
    <div class="src">${esc(t.source || '')}${t.date ? ' &bull; ' + esc(t.date) : ''}${
      t.image_source && t.image_source !== t.source ? credit(t) : ''}</div>
  </div>
</div>`;
  },

  /** Pure picture tile — a harvested infographic with a one-line caption. */
  visual(t, i, images) {
    const img = picture(t, images);
    const c = pick(i);
    if (!img) {
      return `<div class="tile t-noimg w${t.w || 2}"
        style="background:linear-gradient(125deg,${c},${BRAND.navy})">
        <div class="cap">${esc(t.caption || '')}</div></div>`;
    }
    return `<div class="tile t-visual w${t.w || 2}">
      <img src="${esc(sized(img, pxFor(t.w || 2)))}"${onImgError(`linear-gradient(125deg,${c},${BRAND.navy})`)}>
      ${t.caption || t.image_source
        ? `<div class="cap">${esc(t.caption || '')}${credit(t)}</div>` : ''}</div>`;
  },

  stat(t, i) {
    return `<div class="tile t-stat w${t.w || 1}" style="background:${t.color || pick(i + 2)}">
      <div class="n">${esc(t.value)}</div><div class="l">${esc(t.label)}</div></div>`;
  },

  image(t, i, images) {
    const img = picture(t, images);
    // No picture available (no article photo, and image generation failed or
    // was capped). Fall back to a branded caption panel rather than a quote,
    // so a missing illustration still reads as a deliberate design element.
    if (!img) {
      const c = pick(i);
      return `<div class="tile t-noimg w${t.w || 1}"
        style="background:linear-gradient(125deg,${c},${BRAND.navy})">
        <div class="cap">${esc(t.caption || '')}</div></div>`;
    }
    const c = pick(i);
    return `<div class="tile t-image w${t.w || 1}${t.hero ? ' t-hero' : ''}">
      <img src="${esc(img)}"${onImgError(`linear-gradient(125deg,${c},${BRAND.navy})`)}>
      ${t.caption ? `<div class="cap">${esc(t.caption)}</div>` : ''}</div>`;
  },

  quote(t) {
    return `<div class="tile t-quote w${t.w || 1}">
      <div class="q">&ldquo;${esc(t.text)}&rdquo;</div>
      ${t.attribution ? `<div class="who">&mdash; ${esc(t.attribution)}</div>` : ''}</div>`;
  },

  chart(t) {
    const url = t.chart_url || chartUrl(specToChart(t.spec), (t.w || 1) >= 2 ? 760 : 420, 400);
    return `<div class="tile t-chart w${t.w || 1}">
      <div class="head">${t.kicker ? `<div class="k">${esc(t.kicker)}</div>` : ''}<h3>${esc(t.title || '')}</h3></div>
      <div class="plot"><img src="${esc(url)}"></div>
      ${t.caption ? `<div class="cap">${esc(t.caption)}</div>` : ''}</div>`;
  },

  matrix(t) {
    const cells = (t.cells || []).slice(0, 4).map((c, i) =>
      `<div class="cell" style="background:${pick(i)}"><b>${esc(c.title)}</b>${
        c.detail ? `<span>${esc(c.detail)}</span>` : ''}</div>`).join('');
    const x = (t.x_labels || []).map((l) => `<div>${esc(l)}</div>`).join('');
    const y = (t.y_labels || []).map((l) => `<div>${esc(l)}</div>`).join('');
    return `<div class="tile t-matrix w${t.w || 2}">
      <h3>${esc(t.title || '')}</h3>
      <div class="mx">
        <div class="ylab"><div></div>${y}</div>
        <div class="grid"><div class="xlab">${x}</div><div class="cells">${cells}</div></div>
      </div></div>`;
  },

  ranked(t) {
    const items = (t.items || []).slice(0, 8);
    const max = Math.max(1, ...items.map((r) => Number(r.value) || 0));
    const rows = items.map((r, i) => {
      const pctRaw = ((Number(r.value) || 0) / max) * 100;
      const pct = Math.max(12, Math.min(100, pctRaw));
      return `<div class="rk">
        <div class="no" style="background:${pick(i)}">${i + 1}</div>
        <div class="bar"><i style="width:${pct.toFixed(0)}%;background:${pick(i)}33"></i><span>${esc(r.label)}</span></div>
        <div class="v">${esc(r.display || r.value)}</div></div>`;
    }).join('');
    return `<div class="tile t-ranked w${t.w || 1}"><h3>${esc(t.title || '')}</h3>${rows}</div>`;
  },

  compare(t) {
    const cols = t.columns || [];
    const head = `<tr><th>${esc(t.row_header || '')}</th>${cols.map((c) => `<th>${esc(c)}</th>`).join('')}</tr>`;
    const body = (t.rows || []).map((r) => {
      const cells = (r.values || []).map((v, i) => {
        if (typeof v === 'number') {
          const lvl = Math.max(0, Math.min(3, Math.round(v)));
          const shade = ['#E3EAEE', pick(i) + '66', pick(i) + 'AA', pick(i)][lvl];
          return `<td><span class="dot" style="background:${shade}"></span></td>`;
        }
        return `<td>${esc(v)}</td>`;
      }).join('');
      return `<tr><td>${esc(r.label)}</td>${cells}</tr>`;
    }).join('');
    return `<div class="tile t-compare w${t.w || 2}">
      <h3>${esc(t.title || '')}</h3>
      <table>${head}${body}</table></div>`;
  },

  /** Left-to-right architecture diagram: boxes joined by arrows. */
  pipeline(t) {
    const nodes = (t.nodes || []).slice(0, 5);
    const inner = nodes.map((n, i) => {
      const box = `<div class="node" style="background:${pick(i)}">
        <b>${esc(n.name)}</b>${n.detail ? `<span>${esc(n.detail)}</span>` : ''}</div>`;
      return i < nodes.length - 1 ? box + `<div class="arw">&#9654;</div>` : box;
    }).join('');
    return `<div class="tile t-pipe w${t.w || 3}">
      <h3>${esc(t.title || '')}</h3><div class="pipe">${inner}</div></div>`;
  },

  /** The week as a horizontal timeline. */
  timeline(t) {
    const evs = (t.events || []).slice(0, 6).map((e, i) =>
      `<div class="ev" style="--c:${pick(i)}">
         <style>.tl .ev:nth-child(${i + 1})::before{background:${pick(i)}}</style>
         <div class="d">${esc(e.date)}</div><div class="t">${esc(e.label)}</div></div>`).join('');
    return `<div class="tile t-time w${t.w || 3}">
      <h3>${esc(t.title || '')}</h3><div class="tl">${evs}</div></div>`;
  },

  /** Maturity / evolution staircase — each step wider and darker than the last. */
  layers(t) {
    const steps = (t.steps || []).slice(0, 5);
    const inner = steps.map((s, i) => {
      const width = 55 + (i * (45 / Math.max(1, steps.length - 1)));
      return `<div class="step" style="background:${pick(i)};width:${width.toFixed(0)}%">
        <b>${esc(s.name)}</b>${s.detail ? `<span>${esc(s.detail)}</span>` : ''}</div>`;
    }).join('');
    return `<div class="tile t-layers w${t.w || 2}">
      <h3>${esc(t.title || '')}</h3><div class="lay">${inner}</div></div>`;
  },

  flow(t) {
    const stages = (t.stages || []).map((s, i) => `
      <div class="stage">
        <div class="name" style="background:${pick(i)}">${esc(s.name)}</div>
        <div class="steps">${(s.steps || []).map((p) =>
          `<div class="step">${esc(typeof p === 'string' ? p : p.label)}</div>`).join('')}</div>
      </div>`).join('');
    return `<div class="tile t-flow w${t.w || 3}"><h3>${esc(t.title || '')}</h3>${stages}</div>`;
  },

  tool(t, i) {
    return `<div class="tile t-tool w${t.w || 1}" style="background:${pick(i + 3)}">
      <b>${esc(t.name)}</b><span>${esc(t.what)}</span></div>`;
  },

  takeaway(t, i) {
    return `<div class="tile t-take w${t.w || 1}">
      <div class="n">${(t.index || i + 1)}</div><b>${esc(t.title)}</b><span>${esc(t.detail)}</span></div>`;
  },
};


/* ------------------------------------------------------------------ */
/* page packer                                                         */
/* ------------------------------------------------------------------ */
/**
 * Layout arithmetic belongs in code, not in a prompt.
 *
 * Gemini cannot see how tall its tiles render, so asking it to fill a page to
 * 230mm will always miss — sections overflow onto a half-empty continuation
 * page, or stop short and strand white space. Instead it just supplies tiles in
 * priority order, and this packs them into pages that are actually full.
 *
 * Heights below are measured from the CSS above, in millimetres.
 */
const TILE_MM = {
  story:    78,   // 32mm picture + ~46mm of text
  visual:   70,   // 58mm image + caption
  image:    70,
  chart:    82,
  flow:    112,
  layers:   88,
  matrix:   76,
  ranked:   76,
  compare:  74,
  timeline: 64,
  pipeline: 58,
  quote:    32,
  stat:     26,
  takeaway: 26,
  tool:     20,
};

function tileMm(t) {
  let h = TILE_MM[t.type] || 40;
  if (t.type === 'story' && !t.image_url && !t.ai_key) h -= 19;   // no picture
  if (t.type === 'flow')   h = 22 + (t.stages || []).length * 15;
  if (t.type === 'layers') h = 20 + (t.steps  || []).length * 17;
  if (t.type === 'ranked') h = 22 + (t.items  || []).length * 9;
  if (t.type === 'compare')h = 30 + (t.rows   || []).length * 9;
  return h;
}

/** Height of one packed row = tallest tile in it, plus the row gap. */
const rowMm = (row) => Math.max(...row.map(tileMm)) + 6;

/**
 * Pack tiles into pages.
 *   budget  usable millimetres per page, after masthead, band, heading, footer
 *   maxPages hard ceiling; anything that will not fit is dropped, so the issue
 *            never runs long
 */
function packPages(tiles, budgets, maxPages) {
  const rows = packRows(tiles.slice());
  const pages = [];
  let page = [], used = 0;
  const budgetFor = (i) => budgets[Math.min(i, budgets.length - 1)];

  for (const row of rows) {
    const h = rowMm(row);
    if (used + h > budgetFor(pages.length) && page.length) {
      pages.push(page);
      if (pages.length >= maxPages) return pages;   // drop the remainder
      page = []; used = 0;
    }
    page.push(row); used += h;
  }
  if (page.length) pages.push(page);
  return pages.slice(0, maxPages);
}

/* Greedy packer: fill rows to a width of 3. */
function packRows(items) {
  const rows = [];
  let row = [], used = 0;
  for (const it of items) {
    const w = Math.max(1, Math.min(3, Number(it.w) || 1));
    it.w = w;
    if (used + w > 3) { if (row.length) rows.push(row); row = []; used = 0; }
    row.push(it); used += w;
    if (used === 3) { rows.push(row); row = []; used = 0; }
  }
  if (row.length) rows.push(row);
  return rows;
}

function renderTiles(items, images, offset = 0) {
  return packRows(items.slice()).map((row) =>
    `<div class="row">${row.map((t, j) => {
      const fn = TILE[t.type];
      return fn ? fn(t, offset + j, images) : '';
    }).join('')}</div>`
  ).join('\n');
}

/* ------------------------------------------------------------------ */
/* sections                                                            */
/* ------------------------------------------------------------------ */
const SECTION = {
  cover(s, issue, images) {
    const chips = (s.topics || []).map((t, i) =>
      `<div class="chip" style="background:${pick(i)}">${esc(t)}</div>`).join('');
    // hero_url = a direct image URL (Pollinations / a real photo)
    // hero_ai_key = a generated image held in the `images` map (Nano Banana)
    const heroSrc = s.hero_url || (s.hero_ai_key ? images[s.hero_ai_key] : null);
    const hero = heroSrc
      ? `<div class="row"><div class="tile t-image t-hero w3">
         <img src="${esc(sized(heroSrc, 1800))}"${onImgError(`linear-gradient(115deg,${BRAND.navy},${BRAND.cyan})`)}>
         ${s.hero_caption || s.image_source
           ? `<div class="cap">${esc(s.hero_caption || '')}${credit(s)}</div>` : ''}</div></div>`
      : '';
    // The tagline itself now lives in the running header, so it appears on every
    // page. The cover only needs the issue line, the topic chips and the hero.
    return `
<div class="meta-line">Issue ${esc(issue.issue_no || '')} &nbsp;&bull;&nbsp; ${esc(issue.week_label || '')}</div>
${s.intro ? `<div class="sec-summary">${esc(s.intro)}</div>` : ''}
${chips ? `<div class="chips">${chips}</div>` : ''}
${hero}`;
  },

  tiles(s, issue, images) {
    return renderTiles(s.items || [], images);
  },

  sources(s) {
    return `<div class="sources">` + (s.items || []).map((u, i) =>
      `<div>${i + 1}. ${esc(u.title || '')} &mdash; ${esc(u.url)}</div>`).join('') + `</div>`;
  },
};

function buildBody(issue, images = {}) {
  const sections = issue.sections || [];
  const cover    = sections.find((x) => x.type === 'cover');
  const sources  = sections.find((x) => x.type === 'sources');
  const tileSecs = sections.filter((x) => x.type === 'tiles');

  /* Every tile Gemini produced, in the order it produced them. Section
     boundaries are deliberately ignored: the packer decides where pages break,
     because only it knows how tall each tile renders. */
  const allTiles = tileSecs.flatMap((sec) => sec.items || []);

  /* ------------------------------------------------------------------
     PAGE FILL - the two numbers to tune if the layout is not right.

     These are budgets in the packer's own units, not true millimetres: the
     TILE_MM table is an approximation of rendered height, so the budget has
     been scaled to match what Chromium actually produces.

       Pages coming out HALF EMPTY   -> raise PAGE_N_MM by 40
       Content spilling to a 5th page -> lower PAGE_N_MM by 40
       Cover page too empty / too full -> adjust PAGE_1_MM by 40

     One adjustment is usually enough. Change it here, or in the Build HTML
     node in n8n - the constants are near the top of buildBody().
     ------------------------------------------------------------------ */
  const PAGE_1_MM = 215;        // page 1 also carries the cover block
  const PAGE_N_MM = 300;        // pages 2-4: band + heading + tiles
  const MAX_PAGES = 4;          // hard ceiling; extra tiles are dropped

  const pages = packPages(allTiles, [PAGE_1_MM, PAGE_N_MM], MAX_PAGES);

  /* One band per page, taken from the section summaries in order. */
  const bands = tileSecs.map((x) => x.summary).filter(Boolean);
  const heads = tileSecs.map((x) => x.heading).filter(Boolean);

  const blocks = [];

  const rowsHtml = (rows, i) => rows.map((row) =>
    `<div class="row">${row.map((t, j) => {
      const fn = TILE[t.type];
      return fn ? fn(t, i * 7 + j, images) : '';
    }).join('')}</div>`).join('\n');

  pages.forEach((rows, i) => {
    const band = bands[i] ? `<div class="sec-summary">${esc(bands[i])}</div>` : '';
    const head = heads[i] ? `<div class="sec-title">${esc(heads[i])}</div>` : '';

    if (i === 0) {
      // Page 1: the cover block, then tiles filling the rest of the sheet.
      blocks.push(`<div class="sec">` +
        (cover ? SECTION.cover(cover, issue, images) : '') +
        head + rowsHtml(rows, i) + `</div>`);
    } else {
      blocks.push(`<div class="sec pagebreak">${band}${head}${rowsHtml(rows, i)}</div>`);
    }
  });

  if (sources) {
    blocks.push(`<div class="sec">` +
      (sources.heading ? `<div class="sec-title">${esc(sources.heading)}</div>` : '') +
      SECTION.sources(sources, issue, images) + `</div>`);
  }

  return `<!DOCTYPE html><html><head><meta charset="utf-8">
<title>${esc(issue.title || 'InfiniAI Pulse')}</title>
<style>${css()}</style></head><body>
${blocks.join('\n')}
</body></html>`;
}

/**
 * Running header — repeats on every page.
 * Chromium's header context is deliberately crippled: no flexbox, no grid,
 * no external assets, no web fonts. Two-column layouts silently collapse.
 * So the whole masthead is one image lifted from the InfiniAI Pulse template.
 */
function buildHeader(assets, issue = {}) {
  const strip = assets.headerStrip || assets.logoInfiniAI;

  // NOTE: no tagline band here any more. A running header is rendered once and
  // stamped on every page, so it can only ever carry one fixed string. The
  // summary band now lives in the body, once per section, so each one can
  // describe the page it introduces.
  return `<!DOCTYPE html><html><head><meta charset="utf-8"><style>
html,body{margin:0;padding:0;width:100%;
          -webkit-print-color-adjust:exact;print-color-adjust:exact;}
img{display:block;width:100%;height:auto;border:0;}
</style></head><body><img src="${strip}"></body></html>`;
}

/** Running footer — "Page N" left, "AI & Data Office" right, every page. */
function buildFooter() {
  return `<!DOCTYPE html><html><head><meta charset="utf-8"><style>
html,body{margin:0;padding:0;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.wrap{width:100%;padding:0 12mm;display:flex;justify-content:space-between;
      align-items:center;font-family:Arial,Helvetica,sans-serif;
      font-size:9.5pt;color:#4F959D;letter-spacing:.2px;}
</style></head><body>
  <div class="wrap">
    <div>Page <span class="pageNumber"></span></div>
    <div>AI &amp; Data Office</div>
  </div>
</body></html>`;
}

function build(issue, assets, images) {
  return {
    index:  buildBody(issue, images),
    header: buildHeader(assets, issue),
    footer: buildFooter(),
  };
}


