const ASSETS = {"logoInfiniAI": "data:image/jpeg;base64,", "logoSLT": "data:image/jpeg;base64,", "headerStrip": "data:image/jpeg;base64,", "headerAspect": 7.442};

const inp    = $input.first().json;
const issue  = inp.issue  || inp;      // works with or without the image branch
const images = inp.images || {};

// The cover intro becomes the navy band that repeats on every page.
const cover = (issue.sections || []).find((x) => x.type === 'cover') || {};
issue.tagline = cover.intro || '';

const html = {
  index:  buildBody(issue, images),
  header: buildHeader(ASSETS, issue),
  footer: buildFooter(),
};

const bin = (name, content) => ({
  data: Buffer.from(content, 'utf8').toString('base64'),
  mimeType: 'text/html',
  fileName: name,
  fileExtension: 'html',
});

return [{
  json: {
    issue_no:   issue.issue_no,
    week_label: issue.week_label,
    fileName:   `InfiniAI-Pulse-${(issue.week_label || '').replace(/[^0-9A-Za-z]+/g, '-')}.pdf`,
  },
  binary: {
    index:  bin('index.html',  html.index),
    header: bin('header.html', html.header),
    footer: bin('footer.html', html.footer),
  },
}];
